#!/usr/bin/env python3
"""Build the presentation edition from the canonical working program."""
from pathlib import Path
import copy,json,re

ROOT=Path(__file__).resolve().parents[1]
def read(name):
    s=(ROOT/'work'/name).read_text()
    return json.loads(s[s.index('{'):s.rindex('}')+1])
def write(name,var,data):
    (ROOT/name).write_text('window.'+var+' = '+json.dumps(data,ensure_ascii=False,indent=2)+';\n')
D,P,X=(read(n) for n in ['data.js','planning-data.js','expert-data.js'])

